// Guard: only accept calls carrying the shared token (set CM_TOKEN below
// and the same value in the tool's N8N_TOKEN env var). Leave CM_TOKEN empty to
// disable the check — but then anyone who learns the webhook URL can spend your
// API budget, so prefer setting it.
const CM_TOKEN = '';

// Model config lives HERE, not in the repo — this is the half n8n owns.
const MODEL = 'claude-opus-5';
const MAX_TOKENS = 16000;
const EFFORT = 'high';

const body = $input.first().json.body ?? $input.first().json;
const headers = $input.first().json.headers ?? {};

if (CM_TOKEN && headers['x-cm-token'] !== CM_TOKEN) {
  throw new Error('Brak lub zły X-CM-Token');
}
if (!body || !body.system || !body.schema || !body.input) {
  throw new Error('Payload musi mieć pola: system, schema, input');
}

// Structured outputs: the schema is enforced by the API, so the model physically
// cannot return a shape the tool would reject.
return [{
  json: {
    model: MODEL,
    max_tokens: MAX_TOKENS,
    system: body.system,
    thinking: { type: 'adaptive' },
    output_config: {
      effort: EFFORT,
      format: { type: 'json_schema', schema: body.schema }
    },
    messages: [
      { role: 'user', content: JSON.stringify(body.input) }
    ]
  }
}];

// output_config.format guarantees the first text block is valid JSON matching
// the schema — but check stop_reason first: a refusal or a max_tokens cut leaves
// content empty or truncated, and returning that as an answer would be a lie.
const r = $input.first().json;

if (r.stop_reason === 'refusal') {
  throw new Error('Model odmówił: ' + JSON.stringify(r.stop_details ?? {}));
}
if (r.stop_reason === 'max_tokens') {
  throw new Error('Odpowiedź ucięta na max_tokens — zwiększ MAX_TOKENS w węźle „Zbuduj żądanie”.');
}

const text = (r.content ?? []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Brak treści w odpowiedzi (stop_reason=' + r.stop_reason + ')');
}

return [{ json: JSON.parse(text) }];
